from retrying import retry


def test_times_validation():
    with pytest.raises(ValueError):
        @retry(times=0)
        def f():
            pass

    with pytest.raises(ValueError):
        @retry(times=-1)
        def f():
            pass


def test_exceptions_filtering():
    sleep_calls = []
    @retry(times=3, exceptions=(ValueError,), sleep=sleep_calls.append)
    def f():
        raise TypeError("not handled")

    with pytest.raises(TypeError):
        f()
    assert sleep_calls == []


def test_delays_behavior():
    sleep_calls = []
    @retry(times=4, delays=[0.1, 0.5], sleep=sleep_calls.append)
    def f():
        raise RuntimeError("fail")

    with pytest.raises(RuntimeError):
        f()
    # Attempts = 4, so retries happen 3 times (between attempt 1 and 2, 2 and 3, 3 and 4).
    # delays=[0.1, 0.5] -> 1st retry delay: 0.1, 2nd retry delay: 0.5, 3rd retry delay: 0.5 (keeping last value).
    # No sleep after 4th (final) attempt.
    assert sleep_calls == [0.1, 0.5, 0.5]


def test_delays_none():
    sleep_calls = []
    @retry(times=3, delays=None, sleep=sleep_calls.append)
    def f():
        raise RuntimeError("fail")

    with pytest.raises(RuntimeError):
        f()
    assert sleep_calls == [1, 1]


def test_metadata_preserved():
    @retry()
    def my_func():
        """Docstring here."""
        pass

